function isPalindrome(head) {
  let n = 0;
  for (let c = head; c !== null; c = c.next) n++;
  let left = head;
  for (let i = 0; i < Math.floor(n / 2); i++) {
    let right = head;
    for (let j = 0; j < n - 1 - i; j++) right = right.next;   // walk to the mirror node
    if (left.val !== right.val) return false;
    left = left.next;
  }
  return true;
}

